begin;select plan(11);select ok(to_regclass('public.public_leaderboards')is not null,'safe leaderboard exists');select ok(to_regclass('public.leaderboard_rules')is not null,'rules metadata exists');select ok(has_table_privilege('anon','public.public_leaderboards','SELECT'),'anonymous read');select ok(exists(select 1 from information_schema.columns where table_name='public_leaderboards'and column_name='rank'),'deterministic rank exposed');select ok(exists(select 1 from information_schema.columns where table_name='public_leaderboards'and column_name='calculation_version'),'version exposed');select ok(exists(select 1 from information_schema.columns where table_name='public_leaderboards'and column_name='club_slug'),'club scope exposed');select ok(exists(select 1 from pg_views where viewname='public_leaderboards'and definition ilike'%rating%desc%wins%desc%'),'published ordering');select ok(exists(select 1 from pg_indexes where indexname='leaderboard_rank_idx'),'rank lookup indexed');select ok(exists(select 1 from pg_indexes where indexname='leaderboard_calculation_version_idx'),'freshness indexed');select ok(not has_table_privilege('anon','public.leaderboard_entries','INSERT'),'projection immutable to anon');select ok(not has_table_privilege('authenticated','public.leaderboard_rules','UPDATE'),'rules immutable to clients');select*from finish();rollback;
